// Monta a linha de prospecta_leads a partir do payload do painel.
const p = $('Webhook').first().json.body.prospect;
const mapaWpp = { 'Sim': 'sim', 'Não': 'nao' };

let telefone = (p.telefone || '').replace(/\D/g, '');
if (telefone.length >= 10 && !telefone.startsWith('55')) telefone = '55' + telefone;

return [{ json: {
  place_id:          p.place_id || null,
  empresa:           p.nome_empresa,
  telefone:          telefone || null,
  telefone_original: p.telefone_original || null,
  rating:            p.rating_google || null,
  reviews:           p.reviews_google || null,
  especialidades:    p.especialidades || null,
  site:              p.site_empresa && p.site_empresa !== 'Não informado' ? p.site_empresa : null,
  tem_whatsapp:      mapaWpp[p.has_whatsapp] || 'nao_verificado',
  origem:            p.source || 'painel',
}}];

// Normaliza a resposta da SerpAPI e monta as linhas de prospecta_leads.
const req = $('Webhook Busca').first().json.body || {};
const r = $input.first().json || {};
const pagina = Number(req.pagina) || 1;

const base = {
  termo: req.termo || '',
  ll: req.ll || null,
  pagina,
  engine: 'google_maps',
  origem: 'painel',
};

if (r.error || r.search_metadata?.status === 'Error') {
  const erro = r.error || 'Erro desconhecido na SerpAPI';
  return [{ json: {
    erro,
    local_results: [], leads: [], total_resultados: 0, coordinates: null,
    busca: { ...base, status: 'erro', erro, total_resultados: 0, novos_leads: 0 },
  }}];
}

const results = Array.isArray(r.local_results) ? r.local_results : [];

const leads = results.map((x) => {
  let telefone = (x.phone || '').replace(/\D/g, '');
  if (telefone.length >= 10 && !telefone.startsWith('55')) telefone = '55' + telefone;

  const tipo = Array.isArray(x.type) ? x.type.join(', ') : (x.type || null);

  return {
    place_id:          x.place_id || null,
    empresa:           x.title || 'Nome não disponível',
    telefone:          telefone || null,
    telefone_original: x.phone || null,
    endereco:          x.address || null,
    categoria:         Array.isArray(x.type) ? x.type[0] : (x.type || null),
    especialidades:    tipo,
    rating:            x.rating ?? null,
    reviews:           x.reviews ?? null,
    site:              x.website || null,
    latitude:          x.gps_coordinates?.latitude ?? null,
    longitude:         x.gps_coordinates?.longitude ?? null,
    origem:            'serpapi',
  };
}).filter((l) => l.place_id);   // sem place_id não dá pra deduplicar

const primeira = results[0];
const coordinates = primeira?.gps_coordinates
  ? { lat: primeira.gps_coordinates.latitude, lng: primeira.gps_coordinates.longitude }
  : null;

return [{ json: {
  local_results: results,
  coordinates,
  total_resultados: results.length,
  leads,
  busca: { ...base, status: 'ok', erro: null, total_resultados: results.length, novos_leads: leads.length },
}}];
